test('invoiceTotals calculates VAT after discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 10000, discountPercent: 50, vatRate: 21 },
    ],
  };

  const totals = invoiceTotals(invoice);

  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 50000);
  const afterDiscount = 50000;
  const vat = Math.round(afterDiscount * 0.21);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, totals.subtotal - totals.discount + totals.vat);
});

